#include <iostream>
#include <vector>
#include <algorithm>
#include <string>

using namespace std;

/**
 * Problem: 10502 - Product of digits
 * 
 * 解題思路：
 * 給定一個非負整數 N，尋找最小的正整數 Q，使得 Q 的各位數字之積等於 N。
 * 
 * 策略：
 * 1. 如果 N < 10，則 Q = N 是最小的（例外：如果 N=0，最小的 Q 且積為 0 的是 10，但有些題目要求 Q 為自然數，這裡 N=0 通常輸出 10）。
 *    注意：根據題目 $N$ 是非負整數，如果 $N=1$，輸出 1；如果 $N=0$，輸出 10。
 * 2. 如果 N >= 10，我們應該盡量使用較大的數字作為因數，這樣可以減少 Q 的位數。
 * 3. 從 9 開始嘗試除到 2，如果 N 能被某個數字 d 整除，就將 d 加入結果列表，並令 N = N / d。
 * 4. 重複步驟 3 直到 N 變為 1。
 * 5. 如果最後 N 仍然大於 1，說明無法由 2-9 的數字乘積構成，輸出 -1。
 * 6. 將得到的數字由小到大排序，組合即為最小的 Q。
 */

string solve() {
    long long n;
    if (!(cin >> n)) return "";

    if (n == 0) return "10";
    if (n == 1) return "1";
    if (n < 10) return to_string(n);

    vector<int> digits;
    for (int d = 9; d >= 2; --d) {
        while (n % d == 0) {
            digits.push_back(d);
            n /= d;
        }
    }

    if (n > 1) return "-1";

    sort(digits.begin(), digits.end());
    string res = "";
    for (int d : digits) {
        res += to_string(d);
    }
    return res;
}

int main() {
    int t;
    if (!(cin >> t)) return 0;
    while (t--) {
        string result = solve();
        if (!result.empty()) {
            cout << result << endl;
        }
    }
    return 0;
}
